-- later version created by an administrator.
-- ============================================================================

-- Source documents
insert into public.legal_documents (source_id, title, gazette_reference, published_on, ingested) values ('SRC_PCR_2011', 'Legal Metrology (Packaged Commodities) Rules, 2011 — principal rules', 'G.S.R. 202(E), dated 7 March 2011 · The Gazette of India, Extraordinary, Part II—Section 3—Sub-section (i), No. 124', '2011-03-09', true)
on conflict (source_id) do update set title = excluded.title, gazette_reference = excluded.gazette_reference, published_on = excluded.published_on, ingested = excluded.ingested;

-- Legal Metrology provisions (version 1 = the principal rules as published)
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_CHAPTER_II_APPLICABILITY', '3', null, 'Applicability of Chapter II (retail-sale declarations)', 'Retail-sale declaration requirements do not apply to packages above 25 kg / 25 litre (cement and fertilizer up to 50 kg excepted) or to packages meant for industrial or institutional consumers.', 'The provisions of this Chapter shall not apply to,- (a) packages of commodities containing quantity of more than 25 kg or 25 litre excluding cement and fertilizer sold in bags up to 50 kg; and (b) packaged commodities meant for industrial consumers or institutional consumers.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'APPLICABILITY', 'package_structure', 'INFO', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image","declared_net_quantity"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_PREPACK_DECLARATIONS_REQUIRED', '4', null, 'Pre-packed commodity must bear the required declarations', 'Every pre-packed commodity offered for sale, distribution or delivery must carry all declarations required by these rules, on the package or on a securely affixed label.', 'On and from the commencement of these rules, no person shall pre-pack or cause or permit to be pre-packed any commodity for sale, distribution or delivery unless the package in which the commodity is pre-packed bears thereon, or on a label is securely affixed thereto, such declarations as are required to be made under these rules.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MANDATORY_DECLARATION', 'package_structure', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_STANDARD_PACK_SIZE', '5', null, 'Recommended standard package sizes (Second Schedule)', 'Second Schedule commodities must use the prescribed standard quantities; a non-standard size must carry the prescribed ''non standard size'' declaration prominently on the label.', 'The commodities specified in the Second Schedule shall be packed for sale, distribution or delivery in such standard quantities as are specified in that Schedule: Provided that if a commodity specified in the Second Schedule is packed in a size other than that prescribed in that Schedule, a declaration that ''Not a standard pack size under the Legal Metrology (packaged Commodities) Rules, 2011'' or ''non standard size under the Legal Metrology (packaged Commodities) Rules, 2011'' shall be made prominently on the label of such package.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'NET_QUANTITY', 'net_quantity', 'MEDIUM', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image","declared_net_quantity"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_MANUFACTURER', '6', '(1)(a)', 'Name and address of manufacturer / packer', 'The package must declare the name and address of the manufacturer, and of the packer where different.', 'Every package shall bear thereon or on label securely affixed thereto, a definite, plain and conspicuous declaration made in accordance with the provisions of this chapter as, to- (a) the name and address of the manufacturer, or where the manufacturer is not the packer, the name and address of the manufacturer and packer and for any imported package the name and address of the importer shall be mentioned.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MANUFACTURER_DETAILS', 'manufacturer_name', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_IMPORTER', '6', '(1)(a)', 'Name and address of importer on imported packages', 'An imported package must declare the name and address of the importer.', '... and for any imported package the name and address of the importer shall be mentioned.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'IMPORTER_DETAILS', 'importer_name', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":"IMPORTED"}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_PRODUCT_NAME', '6', '(1)(b)', 'Common or generic name of the commodity', 'The package must declare the common or generic name of the commodity; for multi-product packages, the name and number or quantity of each product.', 'The common or generic names of the commodity contained in the package and in case of packages with more than one product, the name and number or quantity of each product shall be mentioned on the package.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MANDATORY_DECLARATION', 'product_name', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_NET_QUANTITY', '6', '(1)(c)', 'Declaration of net quantity', 'The package must declare net quantity in the standard unit of weight or measure, or the number of articles where sold by number.', 'The net quantity, in terms of the standard unit of weight or measure, of the commodity contained in the package or where the commodity is packed or sold by number, the number of the commodity contained in the package shall be mentioned.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'NET_QUANTITY', 'net_quantity', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_DATE_OF_MANUFACTURE', '6', '(1)(d)', 'Month and year of manufacture, pre-packing or import', 'The package must declare the month and year of manufacture, pre-packing or import. Food articles and cosmetics are governed by their own date-marking laws.', 'The month and year in which the commodity is manufactured or pre-packed or imported shall be mentioned in the package: Provided that for packages containing food articles, the provisions of the Prevention of Food Adulteration Act 1954 (37 of 1954) and the rules made there under shall apply ... Provided also that for packages containing cosmetics products, the provisions of the Drugs and Cosmetics Rules, 1945 shall apply.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'DATE_DECLARATION', 'manufacturing_date', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DATE_CHRONOLOGY', '6', '(1)(d)', 'Internal consistency of declared dates', 'Declared dates must be real calendar dates and internally consistent: a ''best before'' or ''use by'' date cannot precede the declared date of manufacture or packing. This is a consistency check on the declared dates, applied on the face of the declaration.', 'The month and year in which the commodity is manufactured or pre-packed or imported shall be mentioned in the package.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'DATE_DECLARATION', 'best_before', 'HIGH', 'FULLY_MACHINE_CHECKABLE', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_MRP', '6', '(1)(e)', 'Retail sale price (MRP) declaration', 'The package must declare the retail sale price.', 'the retail sale price of the package; Provided that for packages containing alcoholic beverages or spirituous liquor, the State Excise Laws and the rules made there under shall be applicable within the State in which it is manufactured and where the state excise laws and rules made there under do not provide for declaration of retail sale price, the provisions of these rules shall apply.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MRP', 'mrp', 'HIGH', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_MRP_FORM', '2', '(m)', 'Form of the retail sale price declaration', 'The retail sale price must be printed in the prescribed form — ''Maximum retail price Rs ... inclusive of all taxes'' or ''MRP Rs ... incl. of all taxes'' — with the prescribed rounding.', '"retail sale price" means the maximum price at which the commodity in packaged form may be sold to the ultimate consumer and the price shall be printed on the package in the manner given below; ''Maximum or Max. retail price Rs...../₹ inclusive of all taxes or in the form MRP Rs / ₹ incl., of all taxes after taking into account the fraction of less than fifty paise to be rounded off to the preceding rupee and fraction of above 50 paise and up to 95 paise to the rounded off to fifty paise.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MRP', 'mrp', 'MEDIUM', 'FULLY_MACHINE_CHECKABLE', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_DIMENSIONS_RELEVANT', '6', '(1)(f)', 'Dimensions where size is relevant', 'Where size is relevant to the commodity, dimensions must be declared, separately for each differently sized piece.', 'Where the sizes of the commodity contained in the package are relevant, the dimensions of the commodity contained in the package and if the dimensions of the different pieces are different, the dimensions of each such different piece shall be mentioned.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'CATEGORY_SPECIFIC', 'size', 'MEDIUM', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":["GARMENT_HOSIERY","OTHER"],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
