insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DECL_CONSUMER_CARE', '6', '(2)', 'Consumer-complaint contact details', 'The package must show the name, address and telephone number (and e-mail, if available) of the consumer-complaint contact.', 'Every package shall bear the name, address, telephone number, E-mail address, if available, of the person who can be or the office which can be, contacted, in case of consumer complaints.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'CONSUMER_CARE', 'consumer_care_phone', 'MEDIUM', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_STICKER_PROHIBITION', '6', '(3)', 'Stickers altering mandatory declarations', 'Stickers may not be used to make or alter mandatory declarations. Only a sticker showing a reduced MRP is allowed, and it must not cover the original MRP.', 'It shall not be permissible to affix individual stickers on the package for altering or making declaration required under these rules: Provided that for reducing the Maximum Retail Price (MRP), a sticker with the revised lower MRP (inclusive of all taxes) may be affixed and the same shall not cover the MRP declaration made by the manufacturer or the packer, as the case may be, on the label of the package.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MRP', 'mrp_sticker', 'HIGH', 'AI_ASSISTED', true, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_MULTI_UNIT_COMPONENTS', '6', '(5)', 'Commodities packed as multiple components', 'For multi-unit commodities, declarations must appear on the main package with information about accompanying packages, or on each individual package with intimation on the main package.', 'Where a commodity consists of a number of components and these components are packed in two or more units, for sale as a single commodity, the declaration required to be made under sub-rule (1) shall appear on the main package and such package shall also carry information about the other accompanying packages or such declaration may be given on individual packages and intimation to that effect may be given on the main package and if the components are sold as spare parts, all declarations shall be given on each package.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'PACKAGE_TYPE', 'package_structure', 'MEDIUM', 'HUMAN_INSPECTION_REQUIRED', true, '["package_image","physical_inspection"]'::jsonb, '{"product_categories":[],"package_types":["COMBINATION","MULTI_PIECE","GROUP","GIFT"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_CHARACTER_SIZE', '7', '(2) and (3)', 'Minimum height of numerals and letters on the principal display panel', 'Numerals must meet the minimum heights in Table I or Table II by net quantity, and letters must be at least 1 mm (2 mm when blown, formed, moulded, embossed or perforated).', '(2) The height of any numeral in the declaration required under these rules, on the principal display panel shall not be less than,- (i) as shown in Table-I, if the net quantity is declared in terms of weight or volume; (ii) as shown in Table-II, if the net quantity is declared in terms of length, area or number. (3) The height of letters in the declaration shall not be less than 1 mm height and when blown, formed, molded, embossed or perforated, the height of letters shall not be less than 2 mm. Provided that the width of the letter or numeral shall not be less than one third of its height, except in the case of numeral ''1'' and letters (i), (I) and (l). TABLE-I — Upto 200g/ml: 1 mm (2 mm when blown/embossed); Above 200g/ml and upto 500g/ml: 2 mm (4 mm); Above 500g/ml: 4 mm (6 mm). TABLE-II — Upto 100 cm2: 1 mm (2 mm); Above 100 cm2 and upto 500 cm2: 2 mm (4 mm); Above 500 cm2 and upto 2500 cm2: 4 mm (6 mm); Above 2500 cm2: 6 mm (6 mm).', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'CHARACTER_SIZE', 'character_height', 'MEDIUM', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image","physical_measurement"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_PDP_PLACEMENT', '8', '(1)', 'Declarations to appear on the principal display panel', 'All required declarations must appear on the principal display panel, and the quantity declaration must be surrounded by the prescribed clear space.', 'Every declaration required to be made under these rules shall appear on the principal display panel. Provided that the area surrounding the quantity declaration shall be free from printed information. (a) above and below by a space equal to at least the height of the numeral in the declaration, and (b) to the left and right by a space at least twice the height of numeral in the declaration.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'READABILITY', 'principal_display_panel', 'MEDIUM', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
