insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_LEGIBILITY', '9', '(1)(a) and (b)', 'Declarations to be legible, prominent and contrasting', 'Declarations must be legible and prominent, and the MRP and net-quantity numerals must contrast conspicuously with the background.', 'Every declaration which is required to be made on a package under these rules shall be -- (a) legible and prominent; (b) numerals of the retail sale price and net quantity declaration shall be printed, painted or inscribed on the package in a colour that contrasts conspicuously with the background of the label.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'READABILITY', 'readability', 'MEDIUM', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_ADDRESS_COMPLETENESS', '10', '(1) and (2)', 'Completeness of the declared address and corporate name', 'The declared address must be complete enough (including PIN code) for a consumer to locate the manufacturer, packer or importer, and the name must be the actual corporate or business name.', '... manufacturer or packer or the Postal Index Number [PIN] Code so that a consumer can identify and locate the manufacturer or packer or importer, as the case may be. (2) The name of the manufacturer or packer or importer shall be the actual corporate name, or if not incorporated, the name under which the business is conducted by such manufacturer or packer or importer in India.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MANUFACTURER_DETAILS', 'manufacturer_address', 'MEDIUM', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_PHYS_NET_QUANTITY', '11', '(1) and (2)', 'Net quantity to exclude wrappers and to match what the consumer receives', 'The declared net quantity must exclude packaging and must correspond to the quantity actually received by the consumer. Verifying this requires physical measurement, not an image.', '(1) In declaring the net quantity of the commodity contained in a package, the weight of wrappers and materials other than the commodity shall be excluded. (2) Where a commodity in a package is not likely to undergo any variation in weight or measure, on account of the environmental conditions, the quantity declared on the package shall correspond to the net quantity which will be received by the consumer, and the declaration of quantity of such package shall not be qualified by the words ''when packed'' or the like.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'NET_QUANTITY', 'net_quantity', 'HIGH', 'HUMAN_INSPECTION_REQUIRED', true, '["physical_measurement"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_UNITS_STATEMENT', '13', '(2), (3), (4) and (5)', 'Units in which quantity must be expressed', 'Quantity must be expressed in SI units, using gram/millilitre/centimetre below the base unit and kilogram/litre/metre at or above it. Dozen, score or gross must not be used; items sold by number use N or U.', '(2) When expressing a quantity less than,- (a) one kilogram, the unit of weight shall be the gram; (b) one metre, the unit of length shall be the centimetre; ... (f) one litre, the unit of volume shall be the millilitre. (3) When expressing a quantity of equal to or more than- (a) one kilogram, the unit of weight shall be the kilogram ... (4) No number called the dozen, score, gross, great gross or the like shall be specified or indicated on any package. (5) Symbol of units:-(i) No system of units other than the International System of Units shall be used in furnishing the net quantity of the package; (ii) For items sold by number the symbol should be N or U.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'NET_QUANTITY', 'net_quantity_unit', 'MEDIUM', 'FULLY_MACHINE_CHECKABLE', false, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":["RETAIL","GROUP","COMBINATION","MULTI_PIECE","PROMOTIONAL","GIFT","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_TEXTILE_DIMENSIONS', '14', null, 'Dimensions of bed-sheets, sarees, towels and similar commodities', 'Textile commodities must declare the number and finished dimensions of each piece, with dimensions and retail sale price also marked on each individual piece.', 'Where a package contains commodities like bed-sheets, hemmed fabric materials, dhoties, sarees, napkins, pillow-covers, towels, table cloths or similar other commodities, the number and the dimensions of finished size of such commodities shall also be declared on the package or on the label affixed thereto: Provided that where the package contains more than one piece of different dimensions, the package shall also contain a declaration as to the dimensions and the retail sale price of each such piece: Provided further that the dimensions of the commodities and the retail sale price thereof shall also be marked on each individual piece.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'CATEGORY_SPECIFIC', 'size', 'MEDIUM', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":["GARMENT_HOSIERY"],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_USABLE_SHEETS', '16', null, 'Number of usable sheets', 'Sheet products must declare the number of usable sheets and the dimensions of each sheet.', 'In the case of a package containing sheets like aluminum foil, facial tissues, waxed paper, toilet paper or any other type of sheet, the declaration of quantity on the package shall also include a statement as to the number of usable sheets contained in the package and the dimensions of each such sheet.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'NET_QUANTITY', 'usable_sheets', 'LOW', 'AI_ASSISTED', false, '["package_image"]'::jsonb, '{"product_categories":["OTHER"],"package_types":["RETAIL","IMPORTED"],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
