insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_DEALER_COMPLIANT_STOCK', '18', '(1)', 'Dealers must not sell or display non-compliant packages', 'A dealer or importer must not sell, display or store for sale any package that does not comply with the Act and these rules.', 'No wholesale dealer or retail dealer or importer shall sell, distribute, deliver, display or store for sale any commodity in the packaged form unless the package complies with in all respects, the provisions of the Act and these rules.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'DEALER_OBLIGATION', 'package_structure', 'HIGH', 'PARTIALLY_MACHINE_CHECKABLE', true, '["package_image","premises_evidence"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":["RETAIL","WHOLESALE","ECOMMERCE"],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_SALE_ABOVE_MRP', '18', '(2)', 'Sale above the declared retail sale price', 'No one may sell a packaged commodity above the declared retail sale price. Evidence is the price charged, not the label alone.', 'No retail dealer or other person including manufacturer, packer, importer and wholesale dealer shall make any sale of any commodity in packed form at a price exceeding the retail sale price thereof.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MRP', 'price_charged', 'HIGH', 'DOCUMENTARY_CHECK_REQUIRED', true, '["invoice_or_bill","package_image"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":["RETAIL","WHOLESALE","ECOMMERCE"],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_MRP_OBLITERATION', '18', '(5) and (6)', 'Obliterating or altering the declared retail sale price', 'The declared retail sale price must not be obliterated, smudged or altered by anyone in the supply chain.', '(5) No wholesale dealer or retail dealer or other person shall obliterate, smudge or alter the retail sale price, indicated by the manufacturer or the packer or the importer, as the case may be, on the package or on the label affixed thereto. (6) The manufacturer or packer or the importer shall not alter the price on the wrapper once printed and used for packing.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'MRP', 'mrp_alteration', 'HIGH', 'AI_ASSISTED', true, '["package_image"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_EXPORT_PACKAGE_SALE', '25', null, 'Restriction on sale of export packages in India', 'An export package may not be sold in India unless re-packed or relabelled to meet Chapter II declarations.', 'An export package shall not be sold in India unless the manufacturer or packer has re-packed or relabeled the commodity in accordance with the provisions contained in Chapter II, and where any export package is sold in India without such re-packing or re-labeling, such package shall be liable to be seized in accordance with the provisions of the Act.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'IMPORT_PROCEDURE', 'export_package', 'HIGH', 'DOCUMENTARY_CHECK_REQUIRED', true, '["package_image","import_documents"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_REGISTRATION_PACKER', '27', '(1)', 'Registration of manufacturers, packers and importers', 'Manufacturers, packers and importers must be registered with the Director or Controller. This is checked against registration records, not from the package image.', 'Every individual, firm, Hindu undivided family, society, company or corporation who or which pre-packs or imports any commodity for sale, distribution or delivery shall make an application, accompanied by a fee of rupees five hundred, to the Director or the Controller for the registration of his or its name and complete address; and every such application shall be made,- (i) in the case of an applicant pre-packing or importing any commodity on the date of commencement of these rules, within a period of ninety days from such commencement; or (ii) in the case of any applicant who or which commences pre-packing or importing of any commodity after the commencement of these rules, within ninety days from the date on which he or it commences such pre-packing.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'REGISTRATION', 'registration', 'MEDIUM', 'DOCUMENTARY_CHECK_REQUIRED', true, '["registration_record"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
on conflict (rule_key, version) do update set rule_number = excluded.rule_number, title = excluded.title, description = excluded.description, legal_requirement = excluded.legal_requirement, source_document = excluded.source_document, effective_from = excluded.effective_from, category = excluded.category, field = excluded.field, severity = excluded.severity, machine_checkability = excluded.machine_checkability, human_review_required = excluded.human_review_required, required_evidence = excluded.required_evidence, applicability = excluded.applicability, provenance = excluded.provenance;
insert into public.rules (rule_key, rule_number, sub_rule, title, description, legal_requirement, source_document, effective_from, effective_to, status, version, category, field, severity, machine_checkability, human_review_required, required_evidence, applicability, provenance) values ('PCR_ADVERTISEMENT_PRICE', '31', '(1)', 'Retail sale price in advertisements', 'An advertisement that states the retail sale price must also state the net quantity or number contained in the package.', 'Any advertisement mentioning the retail sale price of the pre-packaged commodity shall contain a declaration as to the net quantity or number of the commodity contained in the package and the retail sale price thereof.', 'SRC_PCR_2011', '2011-04-01', null, 'in_force', 1, 'ECOMMERCE', 'listing_declarations', 'MEDIUM', 'DOCUMENTARY_CHECK_REQUIRED', true, '["listing_screenshot"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":["ECOMMERCE","RETAIL"],"origin":null}'::jsonb, 'VERIFIED_FROM_SOURCE')
