-- Exemptions (an exemption resolves to NOT APPLICABLE, never to a pass)
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R3_LARGE_PACKAGES', 'Rule 3 — packages above 25 kg / 25 litre and industrial or institutional supplies', 'Rule 3: ''The provisions of this Chapter shall not apply to,- (a) packages of commodities containing quantity of more than 25 kg or 25 litre excluding cement and fertilizer sold in bags up to 50 kg; and (b) packaged commodities meant for industrial consumers or institutional consumers.''', '["PCR_PREPACK_DECLARATIONS_REQUIRED","PCR_STANDARD_PACK_SIZE","PCR_DECL_MANUFACTURER","PCR_DECL_IMPORTER","PCR_DECL_PRODUCT_NAME","PCR_DECL_NET_QUANTITY","PCR_DECL_DATE_OF_MANUFACTURE","PCR_DATE_CHRONOLOGY","PCR_DECL_MRP","PCR_MRP_FORM","PCR_DECL_CONSUMER_CARE","PCR_CHARACTER_SIZE","PCR_PDP_PLACEMENT","PCR_LEGIBILITY"]'::jsonb, '{"product_categories":[],"package_types":["WHOLESALE"],"transaction_contexts":["WHOLESALE"],"origin":null}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R26_SMALL_PACKAGES', 'Rule 26(a) — packages of ten gram or ten millilitre or less', 'Rule 26(a): ''Nothing contained in these rules shall apply to any package containing a commodity if— (a) the net weight or measure of the commodity is ten gram or ten millilitre or less, if sold by weight or measure; Provided that the declaration in respect of maximum retail price and net quantity shall be declared on packages containing 10g to 20g or 10ml to 20ml.'' The MRP and net-quantity declarations are therefore not exempted for 10-20 g / 10-20 ml packages.', '["PCR_DECL_CONSUMER_CARE","PCR_DECL_DATE_OF_MANUFACTURE","PCR_CHARACTER_SIZE","PCR_PDP_PLACEMENT"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R26_FAST_FOOD', 'Rule 26(b) — fast food packed by a restaurant or hotel', 'Rule 26(b): ''any package containing fast food items packed by restaurant or hotel and the like''.', '["PCR_PREPACK_DECLARATIONS_REQUIRED","PCR_DECL_MANUFACTURER","PCR_DECL_PRODUCT_NAME","PCR_DECL_NET_QUANTITY","PCR_DECL_DATE_OF_MANUFACTURE","PCR_DATE_CHRONOLOGY","PCR_DECL_MRP","PCR_MRP_FORM","PCR_DECL_CONSUMER_CARE","PCR_CHARACTER_SIZE","PCR_PDP_PLACEMENT","PCR_LEGIBILITY"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":null}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R26_AGRICULTURAL_ABOVE_50KG', 'Rule 26(d) — agricultural farm produce in packages above 50 kg', 'Rule 26(d): ''agricultural form produces in packages of above 50 kg.''', '["PCR_PREPACK_DECLARATIONS_REQUIRED","PCR_DECL_MRP","PCR_MRP_FORM","PCR_DECL_CONSUMER_CARE","PCR_STANDARD_PACK_SIZE"]'::jsonb, '{"product_categories":["AGRICULTURAL"],"package_types":["WHOLESALE"],"transaction_contexts":[],"origin":null}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R6_IMPORTER_DOMESTIC', 'Importer declaration applies only to imported packages', 'Rule 6(1)(a) requires the name and address of the importer only ''for any imported package''. A domestically manufactured package therefore has no importer declaration to make.', '["PCR_DECL_IMPORTER"]'::jsonb, '{"product_categories":[],"package_types":[],"transaction_contexts":[],"origin":"DOMESTIC"}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;
insert into public.rule_exemptions (exemption_key, title, explanation, rule_keys, conditions, source_document, effective_from, effective_to) values ('EX_R6_WHOLESALE_MRP', 'Retail sale price declarations are directed at retail packages', 'Rule 6 sits in Chapter II, ''Provisions applicable to packages intended for retail sale''. A wholesale package as defined in rule 2(r) is governed by Chapter III instead.', '["PCR_DECL_MRP","PCR_MRP_FORM"]'::jsonb, '{"product_categories":[],"package_types":["WHOLESALE"],"transaction_contexts":[],"origin":null}'::jsonb, 'SRC_PCR_2011', '2011-04-01', null)
on conflict (exemption_key) do update set title = excluded.title, explanation = excluded.explanation, rule_keys = excluded.rule_keys, conditions = excluded.conditions;

